import {componentValue} from './components.js';
import {PROFILES} from './model.mjs';
export const escapeXML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
export const fontFamilies=['Georgia','Arial','Verdana','Trebuchet MS','Times New Roman','Courier New'];
export function textBinding(b,d,heading=false){if(b.type==='componentPart'){if(b.binding==='abilityTitle'||b.binding==='abilityBody'){const a=d.abilities.find(a=>a.id===b.ref);return a?[a,b.binding==='abilityTitle'?'title':'body']:null;}if(b.binding?.startsWith('ritual')){const r=d.rituals.find(r=>r.id===b.ref);return r?[r,{ritualTitle:'title',ritualMeta:'meta',ritualBody:'body'}[b.binding]]:null;}return ['attrName','skillName'].includes(b.binding)?[b,'displayName']:null;}if(b.type==='name')return [d,'name'];if(b.type==='heading')return [b,'headingText'];if(b.type==='equipment')return heading?[b,'title']:[d,'equipment'];if(b.type==='ability'){const a=d.abilities.find(a=>a.id===b.ref);if(a)return [a,heading?'title':'body'];}if(b.type==='ritualPart'){const r=d.rituals.find(r=>r.id===b.ref);if(r)return [r,b.field||'body'];}if(b.type==='profile'){if(heading)return [b,'customTitle'];return [b,'body'];}if(['text','identity','counter'].includes(b.type))return b.type==='identity'?[d,'role']:[b,heading?'title':'body'];return null;}
export function bindingValue(b,d,heading=false){const binding=textBinding(b,d,heading);if(!binding)return '';return binding[0][binding[1]]??(b.type==='componentPart'?componentValue(b,d):b.type==='profile'?PROFILES[d.profile][heading?0:1]:b.title||'');}
export function richTextSVG(body,b,width,height,measure){const E=escapeXML,style=b.textStyle||{},font=style.family||'Arial',size=Number(style.size||b.font||24),lineHeight=Number(style.lineHeight)||1.42,padding=Number(style.padding)||0,spacing=Number(style.letterSpacing)||0,limit=Math.max(1,width-2*padding),runs=b.richText?.text===body?b.richText.ranges||[]:[];const parts=[];let x=0,y=size,line=0,overflow=false;
 const chars=[...String(body)],positions=[];let offset=0;for(const ch of chars){const current={...style};for(const run of runs)if(offset>=run.start&&offset<run.end)Object.assign(current,run.style);const fs=Number(current.size)||size,w=measure(ch,fs,current.family||font,!!current.bold)+spacing;if(ch==='\n'||x+w>limit&&x>0){line++;x=0;y+=size*lineHeight;}if(ch!=='\n'){positions.push({ch,x,y,w,style:current,fs,line});x+=w;}offset+=ch.length;}
 const contentHeight=y+padding,totalHeight=contentHeight+padding;let dy=padding;if(style.vertical==='middle')dy=Math.max(padding,(height-contentHeight)/2);if(style.vertical==='bottom')dy=Math.max(padding,height-contentHeight-padding);const widths=new Map();for(const c of positions)widths.set(c.line,c.x+c.w);
 for(const c of positions){const st=c.style,align=st.align||b.align||'left',shift=align==='center'?(limit-widths.get(c.line))/2:align==='right'?limit-widths.get(c.line):0;parts.push(`<text x="${c.x+padding+shift}" y="${c.y+dy}" font-family="${E(st.family||font)}" font-size="${c.fs}" font-weight="${st.bold?'bold':'normal'}" font-style="${st.italic?'italic':'normal'}" text-decoration="${st.underline?'underline':'none'}" fill="${E(st.color||b.textColor||'#deddd5')}" ${st.outline?`stroke="${E(st.outline)}" stroke-width="0.6" paint-order="stroke"`:''}>${E(st.uppercase?c.ch.toUpperCase():c.ch)}</text>`);}
 overflow=totalHeight>height;return {svg:parts.join(''),height:totalHeight,overflow};}
export function applyRange(text,ranges,start,end,style){return {text,ranges:[...ranges,{start:Math.max(0,start),end:Math.min(text.length,end),style}].slice(-200)};}
export function installTextEditor(E){let overlay=null;const $=s=>document.querySelector(s);function edit(e){if(E.mode!=='edit')return;const el=e.target.closest('[data-block]'),b=E.doc.blocks.find(b=>b.id===el?.dataset.block);if(!b||b.locked||!e.target.closest('text'))return;const clickedTitle=b.part!=='content'&&['text','profile','ability','equipment'].includes(b.type)&&el.querySelector('text')===e.target.closest('text'),binding=textBinding(b,E.doc,clickedTitle);if(!binding)return;e.stopImmediatePropagation();E.select(b.id,true,false,true);overlay?.remove();const editor=document.createElement('textarea');editor.className='inline-editor';editor.setAttribute('aria-label','Editar texto diretamente na ficha');editor.value=bindingValue(b,E.doc,clickedTitle);const s=E.scale;Object.assign(editor.style,{left:b.x*s+'px',top:b.y*s+'px',width:Math.max(130,b.w*s)+'px',height:Math.max(55,b.h*s)+'px',fontSize:Math.max(12,b.font*s)+'px',transform:`rotate(${b.rotation||0}deg)`});$('#stageWrap').append(editor);overlay=editor;editor.focus();editor.select();let cancelled=false,done=false;function finish(){if(done)return;done=true;if(!cancelled&&editor.value!==bindingValue(b,E.doc,clickedTitle))E.change(()=>{binding[0][binding[1]]=editor.value;delete b.richText;},true,true);editor.remove();overlay=null;}editor.addEventListener('blur',finish);editor.addEventListener('keydown',ev=>{ev.stopPropagation();if(ev.key==='Escape'){cancelled=true;finish();}else if((ev.ctrlKey||ev.metaKey)&&ev.key==='Enter')finish();});}
 $('#sheet').addEventListener('dblclick',edit,true);
 function format(){const b=E.getBlock();if(!b||b.locked)return;const binding=textBinding(b,E.doc),body=bindingValue(b,E.doc);if(!binding)return;E.modal('Formatação parcial',`<p class="subtle">Selecione um trecho e aplique um estilo. O texto permanece estruturado, sem HTML.</p><textarea id="rangeText" style="width:100%;min-height:180px">${escapeXML(body)}</textarea><div class="pro-toolbar"><button data-range="bold">Negrito</button><button data-range="italic">Itálico</button><button data-range="underline">Sublinhar</button><input id="rangeColor" aria-label="Cor do trecho" type="color" value="#d1f49b"><button data-range="color">Cor</button><input id="rangeSize" aria-label="Tamanho do trecho" type="number" value="24" min="8" max="250"><button data-range="size">Tamanho</button></div>`,`<button class="primary" data-action="close-modal">Concluir</button>`);let start=0,end=0;const ta=$('#rangeText');ta.addEventListener('select',()=>{start=ta.selectionStart;end=ta.selectionEnd;});ta.addEventListener('input',()=>E.change(()=>{binding[0][binding[1]]=ta.value;delete b.richText;}));document.querySelectorAll('[data-range]').forEach(button=>button.onclick=()=>{if(start===end){E.toast('Selecione um trecho do texto.');return;}const key=button.dataset.range,value=key==='color'?$('#rangeColor').value:key==='size'?Number($('#rangeSize').value):true;E.change(()=>{b.richText=applyRange(ta.value,b.richText?.text===ta.value?b.richText.ranges:[],start,end,{[key]:value});},false,true);});}
 async function importFont(file){if(!file)return;if((E.doc.fonts||[]).length>=20)throw Error('Limite de 20 fontes por ficha.');if(file.size>3000000)throw Error('Use uma fonte de até 3 MB.');if(!/\.(woff2?|ttf|otf)$/i.test(file.name))throw Error('Formatos de fonte: WOFF2, WOFF, TTF ou OTF.');const base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file);});const family='Local_'+crypto.randomUUID().replaceAll('-','');const face=new FontFace(family,`url(${base64})`);await face.load();document.fonts.add(face);E.change(()=>{(E.doc.fonts??=[]).push({family,name:file.name,data:base64});if(E.getBlock())(E.getBlock().textStyle??={}).family=family;},true,true);}
 return {format,importFont};}
